package com.example.microsave.repayment.controller;
import com.example.microsave.repayment.dto.RepaymentDTO;import com.example.microsave.repayment.service.RepaymentService;import jakarta.validation.Valid;import java.util.List;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/repayments")public class RepaymentController{private final RepaymentService s;public RepaymentController(RepaymentService s){this.s=s;}@GetMapping public List<RepaymentDTO>all(){return s.all();}@GetMapping("/{id}")public RepaymentDTO one(@PathVariable Long id){return s.one(id);}@GetMapping("/loan/{loanId}")public List<RepaymentDTO>loan(@PathVariable Long loanId){return s.byLoan(loanId);}@PostMapping@ResponseStatus(HttpStatus.CREATED)public RepaymentDTO create(@Valid@RequestBody RepaymentDTO d){return s.create(d);}@PutMapping("/{id}")public RepaymentDTO update(@PathVariable Long id,@Valid@RequestBody RepaymentDTO d){return s.update(id,d);}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@PathVariable Long id){s.delete(id);}}
